mapper.select:
SELECT create_time::date as reportDate, 'summary' as reportType, COALESCE(SUM(total_amount), 0) as totalSalesAmount, COUNT(*) as totalOrderCount, COALESCE(AVG(total_amount), 0) as avgOrderAmount FROM sales_out WHERE status = 1
AND create_time::date BETWEEN #{startDate} AND #{endDate}
GROUP BY create_time::date ORDER BY reportDate DESC

SELECT create_time::date as reportDate, 'summary' as reportType, COALESCE(SUM(total_amount), 0) as totalPurchaseAmount, COUNT(*) as totalOrderCount, COALESCE(AVG(total_amount), 0) as avgOrderAmount FROM purchase_in WHERE status = 1
AND create_time::date BETWEEN #{startDate} AND #{endDate}
GROUP BY create_time::date ORDER BY reportDate DESC

SELECT i.id, i.product_id as productId, i.product_name as productName, i.product_code as productCode, i.warehouse_name as warehouseName, i.location_name as locationName, i.quantity, p.min_stock as minQuantity, p.min_stock as maxQuantity, i.cost as unitPrice, i.quantity * i.cost as totalAmount, i.production_date as lastInTime, i.expiry_date as lastOutTime FROM inventory i LEFT JOIN product p ON i.product_id = p.id
AND i.warehouse_id = #{warehouseId}
AND i.product_id = #{productId}

SELECT create_time::date as date, COALESCE(SUM(total_amount), 0) as amount, COUNT(*) as count FROM sales_out WHERE status = 1
AND create_time::date BETWEEN #{startDate} AND #{endDate}
GROUP BY create_time::date ORDER BY date ASC

SELECT create_time::date as date, COALESCE(SUM(total_amount), 0) as amount, COUNT(*) as count FROM purchase_in WHERE status = 1
AND create_time::date BETWEEN #{startDate} AND #{endDate}
GROUP BY create_time::date ORDER BY date ASC

SELECT c.id as customerId, c.customer_name as customerName, COALESCE(SUM(so.total_amount), 0) as totalSalesAmount, COUNT(so.id) as orderCount, COALESCE(SUM(so.total_amount), 0) as totalReceivable, COALESCE(SUM(so.total_amount), 0) as receivedAmount, 0 as pendingAmount, MAX(so.create_time) as lastOrderDate, CASE WHEN COALESCE(SUM(so.total_amount), 0) > 0 THEN ROUND(COALESCE(SUM(so.total_amount), 0) / COALESCE(SUM(so.total_amount), 0) * 100, 2) ELSE 0 END as paymentRate, c.level as customerLevel FROM customer c LEFT JOIN sales_out so ON c.id = so.customer_id AND so.status = 1
AND so.create_time::date BETWEEN #{startDate} AND #{endDate}
GROUP BY c.id, c.customer_name, c.level ORDER BY totalSalesAmount DESC

SELECT p.id as productId, p.product_name as productName, pc.category_name as categoryName, COALESCE(SUM(sod.quantity), 0) as salesQuantity, COALESCE(SUM(sod.quantity * sod.unit_price), 0) as salesAmount, COALESCE(SUM(pid.quantity), 0) as purchaseQuantity, COALESCE(SUM(pid.quantity * pid.unit_price), 0) as purchaseAmount, COALESCE(SUM(i.quantity), 0) as stockQuantity, COALESCE(SUM(i.quantity * i.cost), 0) as stockAmount, COALESCE(SUM(sod.quantity * sod.unit_price), 0) - COALESCE(SUM(pid.quantity * pid.unit_price), 0) as profit, CASE WHEN COALESCE(SUM(sod.quantity * sod.unit_price), 0) > 0 THEN ROUND((COALESCE(SUM(sod.quantity * sod.unit_price), 0) - COALESCE(SUM(pid.quantity * pid.unit_price), 0)) / COALESCE(SUM(sod.quantity * sod.unit_price), 0) * 100, 2) ELSE 0 END as profitRate, MAX(sod.create_time) as lastSalesDate FROM product p LEFT JOIN sales_out_detail sod ON p.id = sod.product_id LEFT JOIN purchase_in_detail pid ON p.id = pid.product_id LEFT JOIN product_category pc ON p.category_id = pc.id LEFT JOIN inventory i ON p.id = i.product_id
WHERE sod.create_time::date BETWEEN #{startDate} AND #{endDate}
GROUP BY p.id, p.product_name, pc.category_name ORDER BY salesAmount DESC

SELECT s.id as supplierId, s.supplier_name as supplierName, COALESCE(SUM(pi.total_amount), 0) as totalPurchaseAmount, COUNT(pi.id) as orderCount, COALESCE(SUM(pi.total_amount), 0) as totalPayable, COALESCE(SUM(pi.total_amount), 0) as paidAmount, 0 as pendingAmount, MAX(pi.create_time) as lastOrderDate, CASE WHEN COALESCE(SUM(pi.total_amount), 0) > 0 THEN ROUND(COALESCE(SUM(pi.total_amount), 0) / COALESCE(SUM(pi.total_amount), 0) * 100, 2) ELSE 0 END as paymentRate, 0 as supplierLevel FROM supplier s LEFT JOIN purchase_in pi ON s.id = pi.supplier_id AND pi.status = 1
AND pi.create_time::date BETWEEN #{startDate} AND #{endDate}
GROUP BY s.id, s.supplier_name ORDER BY totalPurchaseAmount DESC
